input.content:
import { connection } from 'next/server'

export default async function Home() {
  await connection()

  const timestamp = new Date()

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>This page is rendered dynamically on every request.</p>
      <p>
        <strong>Current server time:</strong>{' '}
        <time dateTime={timestamp.toISOString()}>{timestamp.toISOString()}</time>
      </p>
      <p>
        <strong>Local representation:</strong> {timestamp.toLocaleString()}
      </p>
    </main>
  )
}

